try:
    import unittest2 as unittest
except ImportError:
    import unittest  # type: ignore

from taf.cloud.cbam.schemas.v3.operation_execution import OperationExecution, OperationExecutionLinks


class TestOperationExecutionLinks(unittest.TestCase):
    def test_createObject(self):
        link1 = 'link1'
        link2 = 'link2'
        link3 = 'link3'
        link4 = 'link4'
        link5 = 'link5'
        link6 = 'link6'
        link7 = 'link7'
        oel = OperationExecutionLinks(self_link=link1, cancel=link2, operation_params=link3, end_notification=link4,
                                      additional_data=link5, list_link=link6, vnf=link7)
        self.assertEqual(oel.self_link, link1)
        self.assertEqual(oel.cancel, link2)
        self.assertEqual(oel.operation_params, link3)
        self.assertEqual(oel.end_notification, link4)
        self.assertEqual(oel.additional_data, link5)
        self.assertEqual(oel.list_link, link6)
        self.assertEqual(oel.vnf, link7)

    def test_createObjectFromResponseDict(self):
        response = {'self': {'href': 'link1'}, 'cancel': {'href': 'link2'}, 'operationParams': {'href': 'link3'},
                    'endNotification': {'href': 'link4'}, 'additionalData': {'href': 'link5'},
                    'list': {'href': 'link6'}, 'vnf': {'href': 'link7'}}
        oel = OperationExecutionLinks.from_response_dict(response_dict=response)
        self.assertEqual(oel.self_link, response['self']['href'])
        self.assertEqual(oel.cancel, response['cancel']['href'])
        self.assertEqual(oel.operation_params, response['operationParams']['href'])
        self.assertEqual(oel.end_notification, response['endNotification']['href'])
        self.assertEqual(oel.additional_data, response['additionalData']['href'])
        self.assertEqual(oel.list_link, response['list']['href'])
        self.assertEqual(oel.vnf, response['vnf']['href'])

    def test_returnObjectAsDict(self):
        response = {'self': {'href': 'link1'}, 'cancel': {'href': 'link2'}, 'operationParams': {'href': 'link3'},
                    'endNotification': {'href': 'link4'}, 'additionalData': {'href': 'link5'},
                    'list': {'href': 'link6'}, 'vnf': {'href': 'link7'}}
        oel = OperationExecutionLinks().from_response_dict(response_dict=response)
        oel_dict = oel.as_dict()
        self.assertEqual(oel_dict['self'], response['self'])
        self.assertEqual(oel_dict['cancel'], response['cancel'])
        self.assertEqual(oel_dict['operationParams'], response['operationParams'])
        self.assertEqual(oel_dict['endNotification'], response['endNotification'])
        self.assertEqual(oel_dict['additionalData'], response['additionalData'])
        self.assertEqual(oel_dict['list'], response['list'])
        self.assertEqual(oel_dict['vnf'], response['vnf'])


class TestOperationExecution(unittest.TestCase):
    def test_createObject(self):
        operation_id = 'operation_id'
        vnf_instance_id = 'vnf_instance_id'
        operation_type = 'operation_type'
        status = 'status'
        is_cancel_pending = 'is_cancel_pending'
        start_time = 'start_time'
        operation_name = 'operation_name'
        cancel_mode = 'cancel_mode'
        error = 'error'
        finish_time = 'finish_time'
        grant_id = 'grant_id'
        operation_params = 'operation_params'
        additional_data = 'additional_data'
        metadata = 'metadata'
        links = 'links'
        oe = OperationExecution(operation_id=operation_id, vnf_instance_id=vnf_instance_id,
                                operation_type=operation_type, status=status, is_cancel_pending=is_cancel_pending,
                                start_time=start_time, operation_name=operation_name, cancel_mode=cancel_mode,
                                error=error, finish_time=finish_time, grant_id=grant_id,
                                operation_params=operation_params, additional_data=additional_data, metadata=metadata,
                                links=links)
        self.assertEqual(oe.operation_id, operation_id)
        self.assertEqual(oe.vnf_instance_id, vnf_instance_id)
        self.assertEqual(oe.operation_type, operation_type)
        self.assertEqual(oe.status, status)
        self.assertEqual(oe.is_cancel_pending, is_cancel_pending)
        self.assertEqual(oe.start_time, start_time)
        self.assertEqual(oe.operation_name, operation_name)
        self.assertEqual(oe.cancel_mode, cancel_mode)
        self.assertEqual(oe.error, error)
        self.assertEqual(oe.finish_time, finish_time)
        self.assertEqual(oe.grant_id, grant_id)
        self.assertEqual(oe.operation_params, operation_params)
        self.assertEqual(oe.additional_data, additional_data)
        self.assertEqual(oe.metadata, metadata)
        self.assertEqual(oe.links, links)

    def test_createObjectFromResponseDict(self):
        response = {'id': 'id', 'vnfInstanceId': 'vnfInstanceId', 'operationType': 'operationType',
                    'status': 'status', 'isCancelPending': 'isCancelPending', 'startTime': 'startTime',
                    'operationName': 'operationName', 'cancelMode': 'cancelMode', 'error': 'error',
                    'finishTime': 'finishTime', 'grantId': 'grantId', 'operationParams': 'operationParams',
                    'additionalData': 'additionalData', 'metadata': 'metadata', '_links': {'self': {'href': 'self_link'}}}
        oe = OperationExecution.from_response_dict(response)
        self.assertEqual(oe.operation_id, response['id'])
        self.assertEqual(oe.vnf_instance_id, response['vnfInstanceId'])
        self.assertEqual(oe.operation_type, response['operationType'])
        self.assertEqual(oe.status, response['status'])
        self.assertEqual(oe.is_cancel_pending, response['isCancelPending'])
        self.assertEqual(oe.start_time, response['startTime'])
        self.assertEqual(oe.operation_name, response['operationName'])
        self.assertEqual(oe.cancel_mode, response['cancelMode'])
        self.assertEqual(oe.error, response['error'])
        self.assertEqual(oe.finish_time, response['finishTime'])
        self.assertEqual(oe.grant_id, response['grantId'])
        self.assertEqual(oe.operation_params, response['operationParams'])
        self.assertEqual(oe.additional_data, response['additionalData'])
        self.assertEqual(oe.metadata, response['metadata'])
        self.assertDictEqual(oe.links.as_dict(), response['_links'])

    def test_returnObjectAsDict(self):
        response = {'id': 'id', 'vnfInstanceId': 'vnfInstanceId', 'operationType': 'operationType',
                    'status': 'status', 'isCancelPending': 'isCancelPending', 'startTime': 'startTime',
                    'operationName': 'operationName', 'cancelMode': 'cancelMode', 'error': 'error',
                    'finishTime': 'finishTime', 'grantId': 'grantId', 'operationParams': 'operationParams',
                    'additionalData': 'additionalData', 'metadata': 'metadata',
                    '_links': {'self': {'href': 'self_link'}}}

        oe = OperationExecution.from_response_dict(response)

        oe_dict = oe.as_dict()
        self.assertEqual(oe_dict['id'], response['id'])
        self.assertEqual(oe_dict['vnfInstanceId'], response['vnfInstanceId'])
        self.assertEqual(oe_dict['operationType'], response['operationType'])
        self.assertEqual(oe_dict['status'], response['status'])
        self.assertEqual(oe_dict['isCancelPending'], response['isCancelPending'])
        self.assertEqual(oe_dict['startTime'], response['startTime'])
        self.assertEqual(oe_dict['operationName'], response['operationName'])
        self.assertEqual(oe_dict['cancelMode'], response['cancelMode'])
        self.assertEqual(oe_dict['error'], response['error'])
        self.assertEqual(oe_dict['finishTime'], response['finishTime'])
        self.assertEqual(oe_dict['grantId'], response['grantId'])
        self.assertEqual(oe_dict['operationParams'], response['operationParams'])
        self.assertEqual(oe_dict['additionalData'], response['additionalData'])
        self.assertEqual(oe_dict['metadata'], response['metadata'])
        self.assertDictEqual(oe_dict['_links'], response['_links'])
